  if(family==="LEADER"){const controlled=Object.fromEntries(Object.entries(inputs).filter(([key])=>metrics.some(m=>m.key===key&&m.families.includes("LEADER"))));return {inputs:controlled,excluded:[],repeatedMistakes:[],operational:{personallyHandledReviews:controlled.LEADER_REVIEW_TURNAROUND?.evidence.length??0,personallyPreparedAllocations:controlled.LEADER_ALLOCATION_COVERAGE?.evidence.length??0}};}return {inputs,excluded,repeatedMistakes,operational};
